arguments.command:
cd /tmp/sv-38396b6daa8244b381aadd2df692ee7c/symbols && \
# Check dynamic symbol table
nm -D libmonosgen-2.0.so 2>/dev/null | wc -l && \
nm -D libmonosgen-2.0.so 2>/dev/null | sort | awk -v a1=0x222098 -v a2=0x222234 -v a3=0x19bac0 -v a4=0x19bc14 '
/^[0-9a-f]+ [TtWw]/ { syms[n]=$1; names[n]=$3; n++ }
END {
  addrs[0]=strtonum(a1); addrs[1]=strtonum(a2); addrs[2]=strtonum(a3); addrs[3]=strtonum(a4)
  for(i=0;i<4;i++) {
    best=""; bestaddr=0
    for(j=0;j<n;j++) {
      saddr=strtonum("0x" syms[j])
      if(saddr <= addrs[i] && saddr > bestaddr) { bestaddr=saddr; best=names[j] }
    }
    printf "0x%x => %s+0x%x\n", addrs[i], best, addrs[i]-bestaddr
  }
}'

